inline TerrainDistanceMaterialSettings3D NormalizeTerrainDistanceMaterialSettings3D(TerrainDistanceMaterialSettings3D settings){settings.detailFadeStart=Clamp(std::isfinite(settings.detailFadeStart)?settings.detailFadeStart:48.f,0.f,100000.f);settings.detailFadeEnd=Clamp(std::isfinite(settings.detailFadeEnd)?settings.detailFadeEnd:192.f,settings.detailFadeStart+.01f,100001.f);settings.macroVariationScale=Clamp(std::isfinite(settings.macroVariationScale)?settings.macroVariationScale:.0065f,.00001f,4.f);settings.macroVariationStrength=Clamp(std::isfinite(settings.macroVariationStrength)?settings.macroVariationStrength:.14f,0.f,.5f);settings.normalDetailStrength=Clamp(std::isfinite(settings.normalDetailStrength)?settings.normalDetailStrength:1.f,0.f,2.f);settings.farRoughnessBoost=Clamp(std::isfinite(settings.farRoughnessBoost)?settings.farRoughnessBoost:.12f,0.f,.5f);return settings;}
inline float TerrainDetailWeight3D(float cameraDistance,const TerrainDistanceMaterialSettings3D& source={}){const TerrainDistanceMaterialSettings3D settings=NormalizeTerrainDistanceMaterialSettings3D(source);if(!settings.enabled)return 1.f;if(!std::isfinite(cameraDistance))return 0.f;const float value=Clamp((cameraDistance-settings.detailFadeStart)/(settings.detailFadeEnd-settings.detailFadeStart),0.f,1.f);return 1.f-value*value*(3.f-2.f*value);}
inline unsigned TerrainMaterialTextureSamples3D(float cameraDistance,bool hasTextures=true,const TerrainDistanceMaterialSettings3D& source={}){if(!hasTextures)return 0;return TerrainDetailWeight3D(cameraDistance,source)>.001f?9u:3u;}
